export const INDEX_HTML = "<!DOCTYPE html><html lang=\"it\" data-theme=\"dark\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no\">\n<meta name=\"theme-color\" content=\"#7c3aed\">\n<meta name=\"apple-mobile-web-app-capable\" content=\"yes\">\n<meta name=\"apple-mobile-web-app-status-bar-style\" content=\"black-translucent\">\n<meta name=\"description\" content=\"FINDO — Cerca, confronta e trova qualsiasi cosa\">\n<title>FINDO</title>\n<link rel=\"manifest\" href=\"/manifest.json\">\n<link rel=\"apple-touch-icon\" href=\"/apple-touch-icon.png\">\n<link rel=\"icon\" type=\"image/png\" sizes=\"192x192\" href=\"/icon-192x192.png\">\n<link rel=\"icon\" type=\"image/png\" sizes=\"512x512\" href=\"/icon-512x512.png\">\n<style>\n*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}\n:root,[data-theme=\"dark\"]{--bg:#0f0b1a;--bg2:#1a1528;--card:#1e1833;--card-hover:#282045;--pri:#7c3aed;--pri2:#a78bfa;--acc:#06b6d4;--acc2:#22d3ee;--ok:#10b981;--warn:#f59e0b;--err:#ef4444;--text:#f3f0ff;--text2:#c4b5fd;--text3:#8b7fb0;--muted:#6b6580;--border:#2d2644;--glass:rgba(126,58,237,0.08);--glass2:rgba(126,58,237,0.04);--sh:0 2px 16px rgba(0,0,0,.35);--r:16px;--r2:12px;--r3:8px;--t:.22s cubic-bezier(.4,0,.2,1);--max:860px}\n[data-theme=\"light\"]{--bg:#f8f7fc;--bg2:#eeeef6;--card:#fff;--card-hover:#f3f0ff;--pri:#7c3aed;--pri2:#6d28d9;--acc:#0891b2;--acc2:#0e7490;--ok:#059669;--warn:#d97706;--err:#dc2626;--text:#1a1033;--text2:#4c3d6e;--text3:#7c6f9a;--muted:#9a93a8;--border:#e0daee;--glass:rgba(124,58,237,0.05);--glass2:rgba(124,58,237,0.02);--sh:0 2px 16px rgba(0,0,0,.06)}\nhtml{font-size:16px;-webkit-text-size-adjust:100%;scroll-behavior:smooth}\nbody{font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",Roboto,sans-serif;background:var(--bg);color:var(--text);min-height:100dvh;overflow-x:hidden;-webkit-tap-highlight-color:transparent}\na{color:var(--acc);text-decoration:none}\nbutton{font:inherit;cursor:pointer;border:none;background:none;color:inherit}\ninput,select,textarea{font:inherit;color:inherit}\n::-webkit-scrollbar{width:5px;height:5px}::-webkit-scrollbar-track{background:transparent}::-webkit-scrollbar-thumb{background:var(--border);border-radius:4px}\n\n/* === SHELL === */\n.shell{max-width:var(--max);margin:0 auto;padding:0 16px}\n\n/* === SEARCH BAR === */\n.search-wrap{position:sticky;top:0;z-index:100;padding:12px 0 8px;background:linear-gradient(var(--bg) 60%,transparent);backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px)}\n.search-box{display:flex;align-items:center;gap:8px;background:var(--card);border:1px solid var(--border);border-radius:var(--r);padding:6px 8px 6px 16px;box-shadow:var(--sh);transition:border var(--t),box-shadow var(--t)}\n.search-box:focus-within{border-color:var(--pri);box-shadow:0 0 0 3px rgba(124,58,237,.18)}\n.search-box input{flex:1;min-width:0;padding:8px 0;background:transparent;border:none;outline:none;font-size:1rem;color:var(--text)}\n.search-box input::placeholder{color:var(--muted)}\n.search-btn{width:40px;height:40px;border-radius:var(--r3);background:var(--pri);color:#fff;display:flex;align-items:center;justify-content:center;font-size:1.2rem;transition:background var(--t)}\n.search-btn:hover,.search-btn:active{background:var(--pri2)}\n.voice-btn{width:36px;height:36px;border-radius:50%;background:transparent;color:var(--text2);display:flex;align-items:center;justify-content:center;font-size:1.1rem;transition:all var(--t)}\n.voice-btn:hover{background:var(--glass);color:var(--acc)}\n.voice-btn.listening{color:var(--err);animation:pulse-mic 1s infinite}\n@keyframes pulse-mic{0%,100%{transform:scale(1)}50%{transform:scale(1.15)}}\n.camera-btn{width:36px;height:36px;border-radius:50%;background:transparent;color:var(--text2);display:flex;align-items:center;justify-content:center;font-size:1.1rem;transition:all var(--t)}\n.camera-btn:hover{background:var(--glass);color:var(--acc)}\n\n/* === INTENT BAR === */\n.intent-bar{display:flex;flex-wrap:wrap;gap:6px;margin:8px 0 4px;align-items:center}\n.intent-tag{display:inline-flex;align-items:center;gap:4px;padding:3px 10px;border-radius:20px;font-size:.75rem;font-weight:600;background:var(--glass);color:var(--pri2);border:1px solid rgba(124,58,237,.15)}\n.intent-tag.kind{background:rgba(6,182,212,.08);color:var(--acc2);border-color:rgba(6,182,212,.15)}\n.intent-tag.warn{background:rgba(245,158,11,.08);color:var(--warn);border-color:rgba(245,158,11,.15)}\n.intent-tag.ok{background:rgba(16,185,129,.08);color:var(--ok);border-color:rgba(16,185,129,.15)}\n\n/* === AI ANSWER === */\n.ai-answer{margin:12px 0 4px;padding:16px 18px;background:linear-gradient(135deg,rgba(124,58,237,.08),rgba(6,182,212,.06));border:1px solid rgba(124,58,237,.12);border-radius:var(--r2);font-size:.92rem;line-height:1.55;color:var(--text2)}\n.ai-answer .ai-label{font-size:.7rem;font-weight:700;text-transform:uppercase;letter-spacing:.5px;color:var(--acc);margin-bottom:6px}\n\n/* === FILTERS === */\n.filters{display:flex;flex-wrap:wrap;gap:8px;margin:8px 0}\n.filter-btn{padding:6px 14px;border-radius:20px;font-size:.78rem;font-weight:600;background:var(--card);color:var(--text3);border:1px solid var(--border);transition:all var(--t)}\n.filter-btn:hover,.filter-btn.on{background:var(--pri);color:#fff;border-color:var(--pri)}\n\n/* === RESULTS === */\n.results-area{margin:8px 0 32px}\n.result-card{background:var(--card);border:1px solid var(--border);border-radius:var(--r2);padding:16px;margin-bottom:10px;transition:all var(--t);position:relative}\n.result-card:hover{border-color:rgba(124,58,237,.25);box-shadow:0 4px 20px rgba(0,0,0,.15)}\n.result-title{font-size:.95rem;font-weight:700;color:var(--text);margin-bottom:4px;display:flex;align-items:center;gap:8px}\n.result-title a{color:var(--text);flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.result-title a:hover{color:var(--acc)}\n.result-desc{font-size:.82rem;color:var(--text3);line-height:1.45;margin-bottom:8px;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}\n.result-meta{display:flex;flex-wrap:wrap;gap:6px;align-items:center;font-size:.75rem}\n.result-meta .price{font-weight:800;color:var(--ok);font-size:.9rem}\n.result-meta .rating{color:var(--warn)}\n.result-meta .source{padding:2px 8px;border-radius:10px;background:var(--glass);color:var(--pri2);font-weight:600}\n.result-meta .dist{color:var(--acc)}\n.result-meta .open{color:var(--ok);font-weight:700}\n.result-meta .closed{color:var(--err);font-weight:700}\n.result-meta .vehicle{color:var(--text3);font-size:.72rem}\n.result-why{display:flex;flex-wrap:wrap;gap:4px;margin-top:8px}\n.result-why span{padding:2px 8px;border-radius:8px;font-size:.68rem;font-weight:600;background:var(--glass2);color:var(--text3)}\n.result-image{width:100%;max-height:180px;object-fit:cover;border-radius:var(--r3);margin:8px 0}\n.result-actions{display:flex;gap:6px;margin-top:8px;flex-wrap:wrap}\n.result-actions button,.result-actions a{padding:5px 12px;border-radius:var(--r3);font-size:.72rem;font-weight:600;transition:all var(--t);display:flex;align-items:center;gap:4px}\n.btn-alert{background:rgba(245,158,11,.08);color:var(--warn);border:1px solid rgba(245,158,11,.15)}\n.btn-alert:hover,.btn-alert.on{background:var(--warn);color:#fff}\n.btn-compare{background:rgba(124,58,237,.08);color:var(--pri2);border:1px solid rgba(124,58,237,.15)}\n.btn-compare:hover,.btn-compare.on{background:var(--pri);color:#fff}\n.btn-share{background:rgba(6,182,212,.08);color:var(--acc);border:1px solid rgba(6,182,212,.15)}\n.btn-share:hover{background:var(--acc);color:#fff}\n.btn-buy{background:var(--ok);color:#fff;font-weight:700;padding:5px 16px}\n.btn-buy:hover{opacity:.9}\n.btn-history{background:var(--glass);color:var(--text3);border:1px solid var(--border)}\n.btn-history:hover{background:var(--glass2);color:var(--text2)}\n.btn-fav{color:var(--muted);font-size:1rem}\n.btn-fav.on{color:var(--err)}\n\n/* === PRICE HISTORY MINI CHART === */\n.price-history-chart{margin-top:8px;padding:8px 0}\n.price-history-chart .chart-label{font-size:.68rem;color:var(--text3);margin-bottom:4px}\n.price-history-chart svg{width:100%;height:40px}\n\n/* === COMPARE MODAL === */\n.modal-overlay{position:fixed;inset:0;background:rgba(0,0,0,.6);z-index:200;display:none;align-items:center;justify-content:center;backdrop-filter:blur(4px)}\n.modal-overlay.show{display:flex}\n.modal{background:var(--card);border:1px solid var(--border);border-radius:var(--r);padding:20px;max-width:720px;width:92%;max-height:80vh;overflow-y:auto;box-shadow:var(--sh)}\n.modal h2{font-size:1.1rem;margin-bottom:12px;color:var(--pri2)}\n.compare-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}\n@media(max-width:480px){.compare-grid{grid-template-columns:1fr}}\n.compare-col{padding:12px;border-radius:var(--r3);background:var(--bg2);border:1px solid var(--border)}\n.compare-col .c-title{font-size:.9rem;font-weight:700;margin-bottom:8px;color:var(--text)}\n.compare-row{display:flex;justify-content:space-between;padding:4px 0;font-size:.78rem;border-bottom:1px solid var(--border)}\n.compare-row:last-child{border:none}\n.compare-row .c-label{color:var(--text3)}\n.compare-row .c-val{color:var(--text);font-weight:600}\n.compare-row .c-best{color:var(--ok);font-weight:700}\n.compare-row .c-worse{color:var(--err)}\n\n/* === SAVED SEARCHES PANEL === */\n.saved-panel{position:fixed;inset:0;background:rgba(0,0,0,.5);z-index:150;display:none;backdrop-filter:blur(3px)}\n.saved-panel.show{display:block}\n.saved-drawer{position:fixed;right:0;top:0;bottom:0;width:min(380px,85vw);background:var(--bg2);border-left:1px solid var(--border);padding:20px;overflow-y:auto;transform:translateX(100%);transition:transform .3s ease}\n.saved-panel.show .saved-drawer{transform:translateX(0)}\n.saved-drawer h3{font-size:1rem;color:var(--pri2);margin-bottom:12px;display:flex;align-items:center;gap:8px}\n.saved-item{padding:10px;border-radius:var(--r3);background:var(--card);border:1px solid var(--border);margin-bottom:8px;display:flex;justify-content:space-between;align-items:center}\n.saved-item .si-query{font-size:.85rem;font-weight:600;color:var(--text)}\n.saved-item .si-meta{font-size:.7rem;color:var(--text3)}\n.saved-item .si-actions{display:flex;gap:6px}\n.saved-item button{font-size:.72rem;padding:3px 8px;border-radius:6px}\n\n/* === VOICE OVERLAY === */\n.voice-overlay{position:fixed;inset:0;background:rgba(0,0,0,.7);z-index:300;display:none;align-items:center;justify-content:center;flex-direction:column}\n.voice-overlay.show{display:flex}\n.voice-overlay .mic-anim{width:80px;height:80px;border-radius:50%;background:var(--err);animation:voice-pulse 1.2s infinite;margin-bottom:16px;display:flex;align-items:center;justify-content:center;font-size:2rem;color:#fff}\n@keyframes voice-pulse{0%,100%{transform:scale(1);box-shadow:0 0 0 0 rgba(239,68,68,.4)}50%{transform:scale(1.08);box-shadow:0 0 0 20px rgba(239,68,68,0)}}\n.voice-overlay .voice-text{font-size:1rem;color:#fff;text-align:center;max-width:300px}\n.voice-overlay .voice-close{margin-top:20px;padding:8px 24px;border-radius:var(--r3);background:var(--card);color:var(--text)}\n\n/* === BARCODE SCANNER === */\n.scanner-overlay{position:fixed;inset:0;background:rgba(0,0,0,.92);z-index:300;display:none;flex-direction:column;align-items:center;justify-content:center}\n.scanner-overlay.show{display:flex}\n.scanner-overlay .scanner-video-wrap{position:relative;width:90%;max-width:400px;aspect-ratio:4/3;border-radius:var(--r2);overflow:hidden;border:2px solid var(--acc);box-shadow:0 0 30px rgba(6,182,212,.2)}\n.scanner-overlay video{width:100%;height:100%;object-fit:cover;border-radius:var(--r2)}\n.scanner-overlay .scanner-crosshair{position:absolute;inset:15%;border:2px solid rgba(6,182,212,.5);border-radius:var(--r3);pointer-events:none}\n.scanner-overlay .scanner-line{position:absolute;left:5%;width:90%;height:2px;background:linear-gradient(90deg,transparent,var(--acc),transparent);animation:scan-line 2s ease-in-out infinite;pointer-events:none}\n@keyframes scan-line{0%{top:15%}50%{top:82%}100%{top:15%}}\n.scanner-overlay .scanner-badge{position:absolute;bottom:8px;left:50%;transform:translateX(-50%);padding:4px 12px;border-radius:20px;background:rgba(0,0,0,.6);color:var(--acc);font-size:.7rem;font-weight:600;backdrop-filter:blur(6px)}\n.scanner-overlay .scanner-hint{color:var(--text3);font-size:.82rem;text-align:center;margin-top:12px}\n.scanner-overlay .scanner-detected{color:var(--ok);font-size:.88rem;text-align:center;margin-top:8px;font-weight:700;min-height:1.2em}\n.scanner-overlay .scanner-close{margin-top:10px;padding:8px 24px;border-radius:var(--r3);background:var(--card);color:var(--text);border:1px solid var(--border)}\n.scanner-manual-input{display:flex;gap:8px;margin-top:10px;width:90%;max-width:400px}\n.scanner-manual-input input{flex:1;padding:8px 12px;border-radius:var(--r3);background:var(--bg2);border:1px solid var(--border);color:var(--text);font-size:.9rem}\n.scanner-manual-input button{padding:8px 16px;border-radius:var(--r3);background:var(--pri);color:#fff;font-weight:600}\n.scanner-overlay .scanner-flash{position:fixed;inset:0;background:#fff;opacity:0;pointer-events:none;transition:opacity .1s;z-index:301}\n.scanner-overlay .scanner-flash.on{opacity:.6}\n\n/* === SHARE MODAL === */\n.share-box{padding:16px}\n.share-box h3{font-size:.95rem;margin-bottom:12px;color:var(--pri2)}\n.share-links{display:flex;gap:10px;flex-wrap:wrap}\n.share-links a{padding:8px 16px;border-radius:var(--r3);font-size:.78rem;font-weight:600;background:var(--glass);color:var(--pri2);border:1px solid var(--border);transition:all var(--t)}\n.share-links a:hover{background:var(--pri);color:#fff}\n\n/* === FAB BUTTONS === */\n.fab-group{position:fixed;bottom:20px;right:16px;display:flex;flex-direction:column;gap:8px;z-index:90}\n.fab{width:48px;height:48px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:1.2rem;box-shadow:var(--sh);transition:all var(--t)}\n.fab:hover{transform:scale(1.1)}\n.fab-saved{background:var(--pri);color:#fff}\n.fab-compare{background:var(--acc);color:#fff}\n.fab-top{background:var(--card);color:var(--text3);border:1px solid var(--border);opacity:0;pointer-events:none;transition:opacity var(--t)}\n.fab-top.show{opacity:1;pointer-events:auto}\n\n/* === EMPTY / LOADING === */\n.loading{display:flex;align-items:center;gap:8px;padding:24px;color:var(--text3);font-size:.88rem}\n.loading .dots::after{content:'';animation:dots 1.5s infinite}\n@keyframes dots{0%{content:''}33%{content:'.'}66%{content:'..'}100%{content:'...'}}\n.empty{padding:40px 20px;text-align:center;color:var(--text3)}\n.empty .e-icon{font-size:3rem;margin-bottom:8px}\n.empty .e-title{font-size:1.1rem;font-weight:700;color:var(--text2);margin-bottom:4px}\n.empty .e-sub{font-size:.82rem}\n\n/* === HEADERS === */\n.header{display:flex;align-items:center;justify-content:space-between;padding:16px 0 4px}\n.header .logo{font-size:1.5rem;font-weight:900;background:linear-gradient(135deg,var(--pri),var(--acc));-webkit-background-clip:text;-webkit-text-fill-color:transparent}\n.header .hdr-btns{display:flex;gap:8px}\n.header .hdr-btn{width:36px;height:36px;border-radius:50%;background:var(--card);border:1px solid var(--border);display:flex;align-items:center;justify-content:center;font-size:.9rem;color:var(--text3);transition:all var(--t)}\n.header .hdr-btn:hover{color:var(--pri2);border-color:var(--pri)}\n\n/* === TAB BAR === */\n.tab-bar{display:flex;gap:0;background:var(--card);border-radius:var(--r3);border:1px solid var(--border);margin:8px 0;overflow:hidden}\n.tab-bar button{flex:1;padding:8px 0;font-size:.78rem;font-weight:600;color:var(--text3);background:transparent;transition:all var(--t);border-right:1px solid var(--border)}\n.tab-bar button:last-child{border-right:none}\n.tab-bar button.on{background:var(--pri);color:#fff}\n\n/* === HISTORY / FAVS === */\n.history-item,.fav-item{padding:10px 12px;border-radius:var(--r3);background:var(--card);border:1px solid var(--border);margin-bottom:6px;display:flex;align-items:center;justify-content:space-between;cursor:pointer;transition:all var(--t)}\n.history-item:hover,.fav-item:hover{border-color:var(--pri)}\n.hi-text{font-size:.85rem;color:var(--text);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;flex:1;min-width:0}\n.hi-time{font-size:.68rem;color:var(--muted);margin-left:8px;white-space:nowrap}\n.hi-del{font-size:.9rem;color:var(--muted);margin-left:8px}\n\n/* === VISUAL SEARCH === */\n.visual-upload{position:fixed;inset:0;background:rgba(0,0,0,.7);z-index:300;display:none;align-items:center;justify-content:center}\n.visual-upload.show{display:flex}\n.visual-box{background:var(--card);border-radius:var(--r);padding:24px;text-align:center;max-width:440px;width:92%}\n.visual-box h3{color:var(--pri2);margin-bottom:12px;font-size:1rem}\n.visual-box input[type=file]{display:none}\n.visual-box .vis-cam-wrap{position:relative;width:100%;aspect-ratio:4/3;border-radius:var(--r2);overflow:hidden;border:2px solid var(--border);margin-bottom:12px;display:none;background:#000}\n.visual-box .vis-cam-wrap.on{display:block}\n.visual-box .vis-cam-wrap video{width:100%;height:100%;object-fit:cover}\n.visual-box .vis-cam-wrap .vis-snap-btn{position:absolute;bottom:10px;left:50%;transform:translateX(-50%);width:56px;height:56px;border-radius:50%;background:rgba(124,58,237,.9);color:#fff;font-size:1.4rem;display:flex;align-items:center;justify-content:center;box-shadow:0 0 16px rgba(124,58,237,.4);border:3px solid #fff;cursor:pointer}\n.visual-box .vis-cam-wrap .vis-switch-btn{position:absolute;top:8px;right:8px;width:32px;height:32px;border-radius:50%;background:rgba(0,0,0,.5);color:#fff;font-size:.9rem;display:flex;align-items:center;justify-content:center;cursor:pointer}\n.visual-box .vis-mode-bar{display:flex;gap:8px;margin-bottom:12px}\n.visual-box .vis-mode-btn{flex:1;padding:10px;border-radius:var(--r3);background:var(--bg2);border:1px solid var(--border);color:var(--text3);font-size:.82rem;font-weight:600;transition:all var(--t)}\n.visual-box .vis-mode-btn.on{background:var(--pri);color:#fff;border-color:var(--pri)}\n.visual-box .upload-area{border:2px dashed var(--border);border-radius:var(--r3);padding:32px;color:var(--text3);font-size:.88rem;cursor:pointer;transition:border var(--t)}\n.visual-box .upload-area:hover{border-color:var(--pri)}\n.visual-box .preview-img{max-width:100%;max-height:200px;border-radius:var(--r3);margin:12px 0}\n.visual-box .vis-desc-input{width:100%;padding:10px 14px;border-radius:var(--r3);background:var(--bg2);border:1px solid var(--border);color:var(--text);font-size:.9rem;margin-bottom:8px}\n.visual-box .vis-desc-input::placeholder{color:var(--muted)}\n.visual-box .search-vis-btn{margin-top:4px;padding:10px 24px;border-radius:var(--r3);background:var(--pri);color:#fff;font-weight:700;width:100%}\n\n/* === TOASTS === */\n.toast{position:fixed;bottom:80px;left:50%;transform:translateX(-50%);padding:10px 20px;border-radius:var(--r3);background:var(--card);border:1px solid var(--border);color:var(--text);font-size:.82rem;z-index:500;opacity:0;transition:opacity .3s;pointer-events:none;box-shadow:var(--sh)}\n.toast.show{opacity:1}\n.toast.toast-ok{border-color:var(--ok);color:var(--ok)}\n.toast.toast-warn{border-color:var(--warn);color:var(--warn)}\n.toast.toast-err{border-color:var(--err);color:var(--err)}\n\n/* === RESPONSIVE === */\n@media(max-width:480px){\n  .search-box{padding:5px 6px 5px 12px}\n  .result-card{padding:12px}\n  .compare-grid{grid-template-columns:1fr}\n  .modal{width:96%;padding:14px}\n}\n</style>\n</head>\n<body>\n\n<div class=\"shell\" id=\"app\">\n  <!-- HEADER -->\n  <div class=\"header\">\n    <div class=\"logo\">FINDO</div>\n    <div class=\"hdr-btns\">\n      <button class=\"hdr-btn\" id=\"btnLang\" title=\"Lingua\">🌐</button>\n      <button class=\"hdr-btn\" id=\"btnTheme\" title=\"Tema\">🌓</button>\n    </div>\n  </div>\n\n  <!-- SEARCH BAR -->\n  <div class=\"search-wrap\">\n    <div class=\"search-box\">\n      <input id=\"searchInput\" type=\"text\" placeholder=\"Cerca qualsiasi cosa...\" autocomplete=\"off\" enterkeyhint=\"search\">\n      <button class=\"camera-btn\" id=\"btnCamera\" title=\"Scansiona barcode\">📷</button>\n      <button class=\"camera-btn\" id=\"btnVisual\" title=\"Ricerca visiva\" style=\"font-size:1rem\">🖼️</button>\n      <button class=\"voice-btn\" id=\"btnVoice\" title=\"Ricerca vocale\">🎤</button>\n      <button class=\"search-btn\" id=\"btnSearch\" title=\"Cerca\">🔍</button>\n    </div>\n    <div class=\"intent-bar\" id=\"intentBar\"></div>\n    <div class=\"filters\" id=\"filters\"></div>\n  </div>\n\n  <!-- AI ANSWER -->\n  <div class=\"ai-answer\" id=\"aiAnswer\" style=\"display:none\">\n    <div class=\"ai-label\">✨ Risposta AI</div>\n    <div id=\"aiText\"></div>\n  </div>\n\n  <!-- TAB BAR -->\n  <div class=\"tab-bar\" id=\"tabBar\">\n    <button class=\"on\" data-tab=\"results\">Risultati</button>\n    <button data-tab=\"favorites\">Preferiti</button>\n    <button data-tab=\"history\">Cronologia</button>\n  </div>\n\n  <!-- RESULTS -->\n  <div class=\"results-area\" id=\"resultsArea\">\n    <div class=\"empty\" id=\"emptyState\">\n      <div class=\"e-icon\">🔍</div>\n      <div class=\"e-title\">Cerca qualsiasi cosa</div>\n      <div class=\"e-sub\">Auto, prodotti, hotel, ristoranti, voli e molto altro</div>\n    </div>\n  </div>\n\n  <!-- FAVORITES -->\n  <div class=\"results-area\" id=\"favoritesArea\" style=\"display:none\">\n    <div class=\"empty\" id=\"favEmpty\">\n      <div class=\"e-icon\">⭐</div>\n      <div class=\"e-title\">Nessun preferito</div>\n      <div class=\"e-sub\">Salva i risultati migliori</div>\n    </div>\n  </div>\n\n  <!-- HISTORY -->\n  <div class=\"results-area\" id=\"historyArea\" style=\"display:none\">\n    <div class=\"empty\" id=\"histEmpty\">\n      <div class=\"e-icon\">🕐</div>\n      <div class=\"e-title\">Nessuna cronologia</div>\n      <div class=\"e-sub\">Le tue ricerche appariranno qui</div>\n    </div>\n  </div>\n</div>\n\n<!-- COMPARE MODAL -->\n<div class=\"modal-overlay\" id=\"compareModal\">\n  <div class=\"modal\">\n    <h2>⚖️ Confronto</h2>\n    <div class=\"compare-grid\" id=\"compareGrid\"></div>\n    <div style=\"text-align:right;margin-top:12px\">\n      <button onclick=\"closeCompare()\" style=\"padding:6px 16px;border-radius:8px;background:var(--glass);color:var(--text3);font-size:.78rem\">Chiudi</button>\n      <button onclick=\"shareCompare()\" style=\"padding:6px 16px;border-radius:8px;background:var(--acc);color:#fff;font-size:.78rem;margin-left:6px;font-weight:600\">Condividi</button>\n    </div>\n  </div>\n</div>\n\n<!-- SAVED SEARCHES PANEL -->\n<div class=\"saved-panel\" id=\"savedPanel\" onclick=\"if(event.target===this)closeSaved()\">\n  <div class=\"saved-drawer\">\n    <h3>💾 Ricerche salvate</h3>\n    <div id=\"savedList\"></div>\n  </div>\n</div>\n\n<!-- VOICE OVERLAY -->\n<div class=\"voice-overlay\" id=\"voiceOverlay\">\n  <div class=\"mic-anim\">🎤</div>\n  <div class=\"voice-text\" id=\"voiceText\">Ascoltando...</div>\n  <button class=\"voice-close\" onclick=\"stopVoice()\">Annulla</button>\n</div>\n\n<!-- BARCODE SCANNER -->\n<div class=\"scanner-overlay\" id=\"scannerOverlay\">\n  <div class=\"scanner-video-wrap\">\n    <video id=\"scannerVideo\" autoplay playsinline muted></video>\n    <div class=\"scanner-crosshair\"></div>\n    <div class=\"scanner-line\"></div>\n    <div class=\"scanner-badge\" id=\"scannerBadge\">Inquadra un codice a barre</div>\n  </div>\n  <div class=\"scanner-detected\" id=\"scannerDetected\"></div>\n  <div class=\"scanner-hint\">Il codice verrà rilevato automaticamente</div>\n  <div class=\"scanner-manual-input\">\n    <input id=\"barcodeInput\" placeholder=\"Inserisci codice manualmente\" type=\"text\">\n    <button onclick=\"searchBarcode()\">Cerca</button>\n  </div>\n  <div class=\"scanner-manual-input\" style=\"margin-top:8px\"><button type=\"button\" onclick=\"document.getElementById('barcodeImgInput').click()\">📷 Leggi barcode da foto</button></div>\n  <input id=\"barcodeImgInput\" type=\"file\" accept=\"image/*\" style=\"display:none\">\n  <div class=\"scanner-flash\" id=\"scannerFlash\"></div>\n  <button class=\"scanner-close\" onclick=\"closeScanner()\">Chiudi</button>\n</div>\n\n\n<!-- VISUAL SEARCH -->\n<div class=\"visual-upload\" id=\"visualOverlay\" onclick=\"if(event.target===this)closeVisual()\">\n  <div class=\"visual-box\">\n    <h3>🖼️ Ricerca visiva</h3>\n    <div class=\"vis-mode-bar\">\n      <button class=\"vis-mode-btn on\" id=\"visModeCam\" onclick=\"setVisMode('cam')\">📷 Fotocamera</button>\n      <button class=\"vis-mode-btn\" id=\"visModeFile\" onclick=\"setVisMode('file')\">📁 Galleria / File</button>\n    </div>\n    <div class=\"vis-cam-wrap\" id=\"visCamWrap\">\n      <video id=\"visVideo\" autoplay playsinline muted></video>\n      <button class=\"vis-snap-btn\" onclick=\"visSnap()\">📸</button>\n      <button class=\"vis-switch-btn\" onclick=\"visSwitchCam()\">🔄</button>\n    </div>\n    <canvas id=\"visCanvas\" style=\"display:none\"></canvas>\n    <div class=\"upload-area\" id=\"uploadArea\" style=\"display:none\" onclick=\"document.getElementById('imgInput').click()\">\n      📁 Tocca per scegliere una foto dal dispositivo\n    </div>\n    <input type=\"file\" id=\"imgInput\" accept=\"image/jpeg,image/png,image/webp,image/heic,image/heif\" style=\"display:none\">\n    <img class=\"preview-img\" id=\"previewImg\" style=\"display:none\">\n    <input class=\"vis-desc-input\" id=\"visDescInput\" placeholder=\"Descrivi cosa vedi nell'immagine...\" type=\"text\">\n    <button class=\"search-vis-btn\" id=\"searchVisBtn\" onclick=\"doVisualSearch()\">🔍 Cerca dove comprare</button>\n  </div>\n</div>\n\n<!-- SHARE MODAL -->\n<div class=\"modal-overlay\" id=\"shareModal\">\n  <div class=\"modal\" style=\"max-width:400px\">\n    <div class=\"share-box\">\n      <h3>📤 Condividi</h3>\n      <div class=\"share-links\" id=\"shareLinks\"></div>\n    </div>\n    <div style=\"text-align:right;margin-top:12px\">\n      <button onclick=\"closeShare()\" style=\"padding:6px 16px;border-radius:8px;background:var(--glass);color:var(--text3);font-size:.78rem\">Chiudi</button>\n    </div>\n  </div>\n</div>\n\n<!-- PRICE HISTORY MODAL -->\n<div class=\"modal-overlay\" id=\"historyModal\">\n  <div class=\"modal\" style=\"max-width:480px\">\n    <h2>📈 Andamento prezzo</h2>\n    <div id=\"historyChart\"></div>\n    <div style=\"text-align:right;margin-top:12px\">\n      <button onclick=\"closeHistoryModal()\" style=\"padding:6px 16px;border-radius:8px;background:var(--glass);color:var(--text3);font-size:.78rem\">Chiudi</button>\n    </div>\n  </div>\n</div>\n\n<!-- FAB -->\n<div class=\"fab-group\">\n  <button class=\"fab fab-saved\" onclick=\"openSaved()\" title=\"Ricerche salvate\">💾</button>\n  <button class=\"fab fab-compare\" onclick=\"openCompare()\" title=\"Confronta\">⚖️</button>\n  <button class=\"fab fab-top\" id=\"fabTop\" onclick=\"scrollTo({top:0,behavior:'smooth'})\" title=\"Torna su\">⬆</button>\n</div>\n\n<!-- TOAST -->\n<div class=\"toast\" id=\"toast\"></div>\n\n<script>\n/* ========== STATE ========== */\nconst S = {\n  query: '', lastResults: [], lastIntent: null, lastAiAnswer: null,\n  favorites: JSON.parse(localStorage.getItem('findo_favs')||'[]'),\n  history: JSON.parse(localStorage.getItem('findo_hist')||'[]'),\n  compareItems: JSON.parse(localStorage.getItem('findo_compare')||'[]'),\n  lang: localStorage.getItem('findo_lang')||'it',\n  theme: localStorage.getItem('findo_theme')||'dark',\n  savedSearches: [], loading: false\n};\n\nconst i18n = {\n  it: { search:\"Cerca qualsiasi cosa\", results:\"Risultati\", favs:\"Preferiti\", hist:\"Cronologia\",\n    empty_search:\"Cerca qualsiasi cosa\", empty_fav:\"Nessun preferito\", empty_hist:\"Nessuna cronologia\",\n    listening:\"Ascoltando...\", no_speech:\"Non ho capito, riprova\",\n    compare_empty:\"Seleziona almeno 2 risultati\", alert_on:\"Alert attivo\", alert_off:\"Alert rimosso\",\n    saved:\"Salvata\", removed:\"Rimossa\", shared:\"Condiviso!\", price:\"Prezzo\", rating:\"Voto\",\n    distance:\"Distanza\", source:\"Fonte\", year:\"Anno\", mileage:\"km\", fuel:\"Aliment.\" },\n  en: { search:\"Search anything\", results:\"Results\", favs:\"Favorites\", hist:\"History\",\n    empty_search:\"Search anything\", empty_fav:\"No favorites\", empty_hist:\"No history\",\n    listening:\"Listening...\", no_speech:\"Didn't catch that, try again\",\n    compare_empty:\"Select at least 2 results\", alert_on:\"Alert on\", alert_off:\"Alert off\",\n    saved:\"Saved\", removed:\"Removed\", shared:\"Shared!\", price:\"Price\", rating:\"Rating\",\n    distance:\"Distance\", source:\"Source\", year:\"Year\", mileage:\"km\", fuel:\"Fuel\" }\n};\n\nfunction t(k){ return (i18n[S.lang]||i18n.it)[k]||k; }\n\n/* ========== INIT ========== */\ndocument.documentElement.setAttribute('data-theme', S.theme);\napplyLang();\n\nfunction applyLang(){\n  document.getElementById('searchInput').placeholder = t('search');\n  document.querySelectorAll('[data-tab]').forEach(b => {\n    if(b.dataset.tab==='results') b.textContent=t('results');\n    if(b.dataset.tab==='favorites') b.textContent=t('favs');\n    if(b.dataset.tab==='history') b.textContent=t('hist');\n  });\n}\n\n/* ========== THEME ========== */\ndocument.getElementById('btnTheme').onclick = () => {\n  S.theme = S.theme==='dark'?'light':'dark';\n  document.documentElement.setAttribute('data-theme', S.theme);\n  localStorage.setItem('findo_theme', S.theme);\n};\n\n/* ========== LANG ========== */\ndocument.getElementById('btnLang').onclick = () => {\n  S.lang = S.lang==='it'?'en':'it';\n  localStorage.setItem('findo_lang', S.lang);\n  applyLang();\n};\n\n/* ========== TABS ========== */\ndocument.querySelectorAll('[data-tab]').forEach(btn => {\n  btn.onclick = () => {\n    document.querySelectorAll('[data-tab]').forEach(b => b.classList.remove('on'));\n    btn.classList.add('on');\n    document.getElementById('resultsArea').style.display = btn.dataset.tab==='results'?'':'none';\n    document.getElementById('favoritesArea').style.display = btn.dataset.tab==='favorites'?'':'none';\n    document.getElementById('historyArea').style.display = btn.dataset.tab==='history'?'':'none';\n    if(btn.dataset.tab==='favorites') renderFavorites();\n    if(btn.dataset.tab==='history') renderHistory();\n  };\n});\n\n/* ========== SEARCH ========== */\nconst searchInput = document.getElementById('searchInput');\nconst btnSearch = document.getElementById('btnSearch');\n\nsearchInput.addEventListener('keydown', e => { if(e.key==='Enter') doSearch(); });\nbtnSearch.onclick = doSearch;\n\nconst LEARN_KEY='findo_learning_v1';\nfunction loadLearning(){try{return JSON.parse(localStorage.getItem(LEARN_KEY)||'{\"sources\":{},\"terms\":{},\"kinds\":{}}')}catch{return {sources:{},terms:{},kinds:{}}}}\nfunction saveLearning(x){localStorage.setItem(LEARN_KEY,JSON.stringify(x))}\nfunction learnEvent(type,r){if(!r)return;const x=loadLearning(),src=String(r.source||'').toLowerCase(),kind=String(S.lastIntent?.kind||'').toLowerCase(),d=type==='negative'?-1:1;if(src)x.sources[src]=(x.sources[src]||0)+d;if(kind)x.kinds[kind]=(x.kinds[kind]||0)+d;for(const t of String(S.query||'').toLowerCase().split(/\\s+/).filter(t=>t.length>=3).slice(0,10))x.terms[t]=(x.terms[t]||0)+d;saveLearning(x);clearTimeout(window._learnTimer);window._learnTimer=setTimeout(()=>{fetch('/api/learn',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({events:[...Object.entries(x.sources).map(([source,v])=>({type:v>0?'positive':'negative',source})),...Object.entries(x.terms).map(([term,v])=>({type:v>0?'positive':'negative',term}))].slice(-100)})}).catch(()=>{})},500)}\nfunction applyLearning(results){const x=loadLearning();return [...results].map(r=>{const src=String(r.source||'').toLowerCase();const bonus=Math.max(-6,Math.min(6,Number(x.sources?.[src]||0)*0.6));return {...r,score:(Number(r.score)||0)+bonus}}).sort((a,b)=>(b.score||0)-(a.score||0))}\n\nasync function doSearch(q) {\n  q = q || searchInput.value.trim();\n  if(!q) return;\n  S.query = q;\n  searchInput.value = q;\n  showLoading();\n  try {\n    let url = `/api/search?q=${encodeURIComponent(q)}`;\n    if('geolocation' in navigator) {\n      try {\n        const pos = await new Promise((res,rej) => navigator.geolocation.getCurrentPosition(res,rej,{timeout:5000}));\n        url += `&lat=${pos.coords.latitude}&lon=${pos.coords.longitude}`;\n      } catch(e) { /* no geo */ }\n    }\n    const r = await fetch(url);\n    if(!r.ok) throw new Error(await r.text());\n    const data = await r.json();\n    S.lastResults = data.results || [];\n    S.lastIntent = data.intent || null;\n    S.lastResults = applyLearning(S.lastResults);\n    S.lastAiAnswer = data.aiAnswer || null;\n    renderIntent(data.intent);\n    renderFilters(data.intent);\n    renderAiAnswer(data.aiAnswer);\n    renderResults(S.lastResults);\n    addHistory(q);\n    // Switch to results tab\n    document.querySelector('[data-tab=\"results\"]').click();\n  } catch(e) {\n    showToast('Errore: ' + e.message, 'err');\n    document.getElementById('resultsArea').innerHTML = `<div class=\"empty\"><div class=\"e-icon\">⚠️</div><div class=\"e-title\">Errore</div><div class=\"e-sub\">${esc(e.message)}</div></div>`;\n  }\n}\n\n/* ========== LOADING ========== */\nfunction showLoading(){\n  document.getElementById('emptyState')?.remove();\n  document.getElementById('resultsArea').innerHTML = '<div class=\"loading\"><span>Caricamento</span><span class=\"dots\"></span></div>';\n}\n\n/* ========== INTENT BAR ========== */\nfunction renderIntent(intent) {\n  if(!intent) { document.getElementById('intentBar').innerHTML=''; return; }\n  const tags = [];\n  if(intent.kind && intent.kind!=='general') tags.push(`<span class=\"intent-tag kind\">${intent.kind}</span>`);\n  if(intent.near) tags.push('<span class=\"intent-tag ok\">📍 Vicino</span>');\n  if(intent.cheap) tags.push('<span class=\"intent-tag ok\">💰 Economico</span>');\n  if(intent.expensive) tags.push('<span class=\"intent-tag warn\">💎 Premium</span>');\n  if(intent.openNow) tags.push('<span class=\"intent-tag ok\">🕐 Aperto ora</span>');\n  if(intent.maxPrice!=null) tags.push(`<span class=\"intent-tag warn\"> sotto €${intent.maxPrice.toLocaleString('it')}</span>`);\n  if(intent.maxMileage!=null) tags.push(`<span class=\"intent-tag warn\">🚗 &lt;${intent.maxMileage.toLocaleString('it')} km</span>`);\n  if(intent.minYear!=null) tags.push(`<span class=\"intent-tag ok\">📅 dal ${intent.minYear}</span>`);\n  if(intent.fuel) tags.push(`<span class=\"intent-tag kind\">⛽ ${intent.fuel}</span>`);\n  if(intent.used) tags.push('<span class=\"intent-tag warn\">🔄 Usato</span>');\n  if(intent.city) tags.push(`<span class=\"intent-tag kind\">🏙️ ${esc(intent.city)}</span>`);\n  document.getElementById('intentBar').innerHTML = tags.join('');\n}\n\n/* ========== FILTERS ========== */\nfunction renderFilters(intent) {\n  if(!intent) { document.getElementById('filters').innerHTML=''; return; }\n  const f = [];\n  f.push({key:'sort-best',label:'Rilevanza',sort:'best'});\n  f.push({key:'sort-price',label:'Prezzo ↑',sort:'price'});\n  f.push({key:'sort-dist',label:'Distanza',sort:'distance'});\n  const html = f.map(x => `<button class=\"filter-btn${intent.sort===x.sort?' on':''}\" onclick=\"reSort('${x.sort}')\">${x.label}</button>`).join('');\n  document.getElementById('filters').innerHTML = html;\n}\n\nfunction reSort(sort) {\n  if(!S.lastIntent) return;\n  S.lastIntent.sort = sort;\n  const sorted = [...S.lastResults];\n  if(sort==='price') sorted.sort((a,b)=>(a.price??1e12)-(b.price??1e12));\n  else if(sort==='distance') sorted.sort((a,b)=>(a.distanceKm??1e12)-(b.distanceKm??1e12));\n  else sorted.sort((a,b)=>(b.score||0)-(a.score||0));\n  S.lastResults = sorted;\n  renderResults(sorted);\n  renderFilters(S.lastIntent);\n}\n\n/* ========== AI ANSWER ========== */\nfunction renderAiAnswer(answer) {\n  const el = document.getElementById('aiAnswer');\n  if(!answer) { el.style.display='none'; return; }\n  el.style.display='';\n  document.getElementById('aiText').textContent = answer;\n}\n\n/* ========== RENDER RESULTS ========== */\nfunction renderResults(results) {\n  const area = document.getElementById('resultsArea');\n  if(!results.length) {\n    area.innerHTML = `<div class=\"empty\"><div class=\"e-icon\">😕</div><div class=\"e-title\">Nessun risultato</div><div class=\"e-sub\">Prova a modificare la ricerca</div></div>`;\n    return;\n  }\n  const compareIds = new Set(S.compareItems.map(c=>c.id));\n  const favIds = new Set(S.favorites.map(f=>f.id));\n  let html = '';\n  for (const r of results) {\n    const isFav = favIds.has(r.id);\n    const isComp = compareIds.has(r.id);\n    const hasAlert = S.savedSearches.some(s => s.query && s.query.includes(S.query));\n    html += `<div class=\"result-card\" data-id=\"${r.id}\">\n      <div class=\"result-title\">\n        <a href=\"${esc(r.url)}\" target=\"_blank\" rel=\"noopener\" onclick=\"learnEvent('positive',S.lastResults.find(x=>x.id==='${r.id}'))\">${esc(r.title)}</a>\n        <button class=\"btn-fav${isFav?' on':''}\" onclick=\"toggleFav('${r.id}')\" title=\"Preferito\">${isFav?'❤️':'🤍'}</button>\n      </div>\n      ${r.image?`<img class=\"result-image\" src=\"${esc(r.image)}\" loading=\"lazy\" alt=\"\" onerror=\"this.style.display='none'\">`:''}\n      <div class=\"result-desc\">${esc(r.description)}</div>\n      <div class=\"result-meta\">\n        ${r.price!=null?`<span class=\"price\">€ ${Number(r.price).toLocaleString('it')}</span>`:''}\n        ${r.rating!=null?`<span class=\"rating\">★ ${r.rating}</span>`:''}\n        <span class=\"source\">${esc(r.source)}</span>\n        ${r.distanceKm!=null?`<span class=\"dist\">📍 ${r.distanceKm} km</span>`:''}\n        ${r.openNow===true?'<span class=\"open\">Aperto</span>':(r.openNow===false?'<span class=\"closed\">Chiuso</span>':'')}\n        ${r.year?`<span class=\"vehicle\">📅 ${r.year}</span>`:''}\n        ${r.mileage!=null?`<span class=\"vehicle\">🛣️ ${Number(r.mileage).toLocaleString('it')} km</span>`:''}\n        ${r.fuel?`<span class=\"vehicle\">⛽ ${esc(r.fuel)}</span>`:''}\n      </div>\n      ${r.why?.length?`<div class=\"result-why\">${r.why.map(w=>`<span>${esc(w)}</span>`).join('')}</div>`:''}\n      <div class=\"result-actions\">\n        <button class=\"btn-alert${hasAlert?' on':''}\" onclick=\"toggleAlert('${r.id}','${esc(S.query)}')\">🔔 ${hasAlert?'Alert on':'Alert'}</button>\n        <button class=\"btn-compare${isComp?' on':''}\" onclick=\"toggleCompare('${r.id}')\">⚖️ ${isComp?'Nel confronto':'Confronta'}</button>\n        <button class=\"btn-share\" onclick=\"shareResult('${r.id}')\">📤</button>\n        ${r.price!=null?`<button class=\"btn-history\" onclick=\"showPriceHistory('${esc(r.url)}')\">📈</button>`:''}\n        ${r.url&&r.price!=null?`<a class=\"btn-buy\" href=\"${esc(r.url)}\" target=\"_blank\" rel=\"noopener\">Acquista →</a>`:''}\n      </div>\n    </div>`;\n  }\n  area.innerHTML = html;\n}\n\n/* ========== FAVORITES ========== */\nfunction toggleFav(id) {\n  const idx = S.favorites.findIndex(f=>f.id===id);\n  if(idx>=0) { S.favorites.splice(idx,1); showToast('Rimosso dai preferiti','warn'); }\n  else {\n    const r = S.lastResults.find(x=>x.id===id);\n    if(r) { S.favorites.push(r); learnEvent('positive',r); showToast('Aggiunto ai preferiti','ok'); }\n  }\n  localStorage.setItem('findo_favs', JSON.stringify(S.favorites));\n  renderResults(S.lastResults);\n}\n\nfunction renderFavorites() {\n  const area = document.getElementById('favoritesArea');\n  if(!S.favorites.length) {\n    area.innerHTML = `<div class=\"empty\" id=\"favEmpty\"><div class=\"e-icon\">⭐</div><div class=\"e-title\">${t('empty_fav')}</div><div class=\"e-sub\">Salva i risultati migliori</div></div>`;\n    return;\n  }\n  let html = '';\n  for (const f of S.favorites) {\n    html += `<div class=\"fav-item\" onclick=\"window.open('${esc(f.url)}','_blank')\">\n      <span class=\"hi-text\">${esc(f.title)}</span>\n      ${f.price!=null?`<span style=\"color:var(--ok);font-weight:700;font-size:.82rem;margin-left:8px\">€${Number(f.price).toLocaleString('it')}</span>`:''}\n      <span class=\"hi-del\" onclick=\"event.stopPropagation();removeFav('${f.id}')\">✕</span>\n    </div>`;\n  }\n  area.innerHTML = html;\n}\n\nfunction removeFav(id) {\n  S.favorites = S.favorites.filter(f=>f.id!==id);\n  localStorage.setItem('findo_favs', JSON.stringify(S.favorites));\n  renderFavorites();\n}\n\n/* ========== HISTORY ========== */\nfunction addHistory(q) {\n  const dup = S.history.findIndex(h=>h.q===q);\n  if(dup>=0) S.history.splice(dup,1);\n  S.history.unshift({q, t:Date.now()});\n  if(S.history.length>50) S.history.length=50;\n  localStorage.setItem('findo_hist', JSON.stringify(S.history));\n}\n\nfunction renderHistory() {\n  const area = document.getElementById('historyArea');\n  if(!S.history.length) {\n    area.innerHTML = `<div class=\"empty\" id=\"histEmpty\"><div class=\"e-icon\">🕐</div><div class=\"e-title\">${t('empty_hist')}</div><div class=\"e-sub\">Le tue ricerche appariranno qui</div></div>`;\n    return;\n  }\n  let html = '';\n  for (const h of S.history) {\n    const ago = timeAgo(h.t);\n    html += `<div class=\"history-item\" onclick=\"doSearch('${esc(h.q)}')\">\n      <span class=\"hi-text\">${esc(h.q)}</span>\n      <span class=\"hi-time\">${ago}</span>\n      <span class=\"hi-del\" onclick=\"event.stopPropagation();delHist('${esc(h.q)}')\">✕</span>\n    </div>`;\n  }\n  area.innerHTML = html;\n}\n\nfunction delHist(q) {\n  S.history = S.history.filter(h=>h.q!==q);\n  localStorage.setItem('findo_hist', JSON.stringify(S.history));\n  renderHistory();\n}\n\nfunction timeAgo(ts) {\n  const s=Math.floor((Date.now()-ts)/1000);\n  if(s<60) return 'ora';\n  if(s<3600) return Math.floor(s/60)+' min';\n  if(s<86400) return Math.floor(s/3600)+' ore';\n  return Math.floor(s/86400)+' giorni';\n}\n\n/* ========== COMPARE ========== */\nfunction toggleCompare(id) {\n  const idx = S.compareItems.findIndex(c=>c.id===id);\n  if(idx>=0) { S.compareItems.splice(idx,1); }\n  else {\n    const r = S.lastResults.find(x=>x.id===id);\n    if(r) {\n      if(S.compareItems.length>=4) { showToast('Massimo 4 elementi nel confronto','warn'); return; }\n      S.compareItems.push(r);\n    }\n  }\n  localStorage.setItem('findo_compare', JSON.stringify(S.compareItems));\n  renderResults(S.lastResults);\n  showToast(S.compareItems.length+' elementi nel confronto');\n}\n\nfunction openCompare() {\n  if(S.compareItems.length<2) { showToast(t('compare_empty'),'warn'); return; }\n  const grid = document.getElementById('compareGrid');\n  const items = S.compareItems;\n  const cols = items.map(item => {\n    const rows = [];\n    rows.push({label:t('price'), val:item.price!=null?`€${Number(item.price).toLocaleString('it')}`:'—'});\n    rows.push({label:t('rating'), val:item.rating!=null?`★ ${item.rating}`:'—'});\n    rows.push({label:t('distance'), val:item.distanceKm!=null?`${item.distanceKm} km`:'—'});\n    rows.push({label:t('source'), val:item.source||'—'});\n    rows.push({label:t('year'), val:item.year||'—'});\n    rows.push({label:t('mileage'), val:item.mileage!=null?`${Number(item.mileage).toLocaleString('it')} km`:'—'});\n    rows.push({label:t('fuel'), val:item.fuel||'—'});\n    return {item, rows};\n  });\n\n  // Find best price\n  const prices = items.filter(i=>i.price!=null).map(i=>i.price);\n  const minPrice = prices.length ? Math.min(...prices) : null;\n\n  let html = '';\n  for (const col of cols) {\n    html += `<div class=\"compare-col\">\n      <div class=\"c-title\"><a href=\"${esc(col.item.url)}\" target=\"_blank\">${esc(col.item.title)}</a></div>\n      ${col.rows.map(r => {\n        const isBest = r.label===t('price') && col.item.price!=null && col.item.price===minPrice;\n        const cls = isBest ? 'c-best' : '';\n        return `<div class=\"compare-row\"><span class=\"c-label\">${esc(r.label)}</span><span class=\"c-val ${cls}\">${esc(r.val)}</span></div>`;\n      }).join('')}\n    </div>`;\n  }\n  grid.innerHTML = html;\n  document.getElementById('compareModal').classList.add('show');\n}\n\nfunction closeCompare(){ document.getElementById('compareModal').classList.remove('show'); }\n\nfunction shareCompare(){\n  const text = S.compareItems.map(i => `${i.title}: €${i.price!=null?Number(i.price).toLocaleString('it'):'?'}`).join('\\n');\n  const shareData = {title:'Confronto FINDO', text:'Confronto FINDO:\\n'+text, url:location.href};\n  if(navigator.share) navigator.share(shareData).catch(()=>{});\n  else { navigator.clipboard.writeText(text).then(()=>showToast(t('shared'),'ok')); }\n  closeCompare();\n}\n\n/* ========== ALERTS ========== */\nasync function toggleAlert(id, query) {\n  if(!query) return;\n  const existing = S.savedSearches.find(s=>s.query===query);\n  if(existing) {\n    await fetch(`/api/saved-searches/${existing.id}`,{method:'DELETE'});\n    showToast(t('alert_off'),'warn');\n  } else {\n    await fetch('/api/saved-searches',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({query,alert:{kind:S.lastIntent?.kind||'general',priceDrop:true}})});\n    showToast(t('alert_on'),'ok');\n  }\n  loadSavedSearches();\n}\n\nasync function loadSavedSearches(){\n  try { S.savedSearches = await (await fetch('/api/saved-searches')).json(); } catch{ S.savedSearches=[]; }\n}\n\nfunction openSaved() {\n  renderSavedList();\n  document.getElementById('savedPanel').classList.add('show');\n}\nfunction closeSaved() { document.getElementById('savedPanel').classList.remove('show'); }\n\nfunction renderSavedList() {\n  const el = document.getElementById('savedList');\n  if(!S.savedSearches.length) { el.innerHTML='<div style=\"color:var(--text3);font-size:.85rem;padding:12px\">Nessuna ricerca salvata</div>'; return; }\n  let html='';\n  for (const s of S.savedSearches) {\n    html += `<div class=\"saved-item\">\n      <div><div class=\"si-query\">${esc(s.query)}</div><div class=\"si-meta\">${s.alert?.priceDrop?'🔔 Alert prezzo':''} · ${s.kind||'generale'}</div></div>\n      <div class=\"si-actions\">\n        <button style=\"background:var(--glass);color:var(--acc)\" onclick=\"doSearch('${esc(s.query)}');closeSaved()\">Cerca</button>\n        <button style=\"background:rgba(239,68,68,.08);color:var(--err)\" onclick=\"delSavedSearch('${s.id}')\">✕</button>\n      </div>\n    </div>`;\n  }\n  el.innerHTML = html;\n}\n\nasync function delSavedSearch(id) {\n  await fetch(`/api/saved-searches/${id}`,{method:'DELETE'});\n  loadSavedSearches();\n  renderSavedList();\n}\n\n/* ========== PRICE HISTORY ========== */\nasync function showPriceHistory(url) {\n  try {\n    const data = await (await fetch(`/api/price-history?url=${encodeURIComponent(url)}`)).json();\n    if(!data.prices?.length) { showToast('Nessun dato storico','warn'); return; }\n    const chart = document.getElementById('historyChart');\n    const prices = data.prices;\n    const min = Math.min(...prices.map(p=>p.price));\n    const max = Math.max(...prices.map(p=>p.price));\n    const range = max-min||1;\n    const w = 320, h = 100, px = 8;\n    const step = (w-2*px) / Math.max(1,prices.length-1);\n    let points = prices.map((p,i) => `${px+i*step},${h-px-((p.price-min)/range)*(h-2*px)}`);\n    const polyline = points.join(' ');\n    const lastPrice = prices[prices.length-1].price;\n    const firstPrice = prices[0].price;\n    const diff = lastPrice - firstPrice;\n    const diffColor = diff<0?'var(--ok)':'var(--err)';\n    const diffText = diff<0?`↓ €${Math.abs(diff).toLocaleString('it')}`:(diff>0?`↑ €${diff.toLocaleString('it')}`:'=');\n\n    chart.innerHTML = `\n      <div style=\"font-size:.78rem;color:var(--text3);margin-bottom:4px\">${esc(data.title||'')} · ${prices.length} rilevamenti</div>\n      <div style=\"font-size:1.1rem;font-weight:700;color:var(--ok);margin-bottom:8px\">€ ${lastPrice.toLocaleString('it')} <span style=\"font-size:.78rem;color:${diffColor}\">${diffText}</span></div>\n      <svg viewBox=\"0 0 ${w} ${h}\" style=\"width:100%;height:auto\">\n        <polyline points=\"${polyline}\" fill=\"none\" stroke=\"var(--ok)\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/>\n        ${prices.map((p,i)=>`<circle cx=\"${px+i*step}\" cy=\"${h-px-((p.price-min)/range)*(h-2*px)}\" r=\"3\" fill=\"var(--ok)\" title=\"${p.date}: €${p.price.toLocaleString('it')}\"/>`).join('')}\n      </svg>\n      <div style=\"display:flex;justify-content:space-between;font-size:.68rem;color:var(--muted);margin-top:4px\">\n        <span>${prices[0].date}</span><span>${prices[prices.length-1].date}</span>\n      </div>`;\n    document.getElementById('historyModal').classList.add('show');\n  } catch(e) { showToast('Errore cronologia prezzi','err'); }\n}\nfunction closeHistoryModal(){ document.getElementById('historyModal').classList.remove('show'); }\n\n/* ========== VOICE SEARCH ========== */\nlet recognition = null;\ndocument.getElementById('btnVoice').onclick = startVoice;\n\nfunction startVoice() {\n  if(!('webkitSpeechRecognition' in window || 'SpeechRecognition' in window)) {\n    showToast('Ricerca vocale non supportata','warn'); return;\n  }\n  const SR = window.SpeechRecognition || window.webkitSpeechRecognition;\n  recognition = new SR();\n  recognition.lang = S.lang==='it'?'it-IT':'en-US';\n  recognition.interimResults = true;\n  recognition.continuous = false;\n\n  recognition.onstart = () => {\n    document.getElementById('voiceOverlay').classList.add('show');\n    document.getElementById('btnVoice').classList.add('listening');\n    document.getElementById('voiceText').textContent = t('listening');\n  };\n  recognition.onresult = (e) => {\n    let transcript = '';\n    for(let i=e.resultIndex;i<e.results.length;i++) transcript += e.results[i][0].transcript;\n    document.getElementById('voiceText').textContent = transcript;\n    if(e.results[0].isFinal) {\n      stopVoice();\n      searchInput.value = transcript;\n      doSearch(transcript);\n    }\n  };\n  recognition.onerror = (e) => {\n    stopVoice();\n    if(e.error==='no-speech') showToast(t('no_speech'),'warn');\n    else showToast('Errore vocale: '+e.error,'err');\n  };\n  recognition.onend = () => stopVoice();\n  recognition.start();\n}\n\nfunction stopVoice() {\n  if(recognition) { try{recognition.stop();}catch(e){} recognition=null; }\n  document.getElementById('voiceOverlay').classList.remove('show');\n  document.getElementById('btnVoice').classList.remove('listening');\n}\n\n/* ========== BARCODE SCANNER (REAL CAMERA) ========== */\nlet scannerStream = null;\nlet scannerRAF = null;\nlet barcodeDetector = null;\nlet scannerCanvas = null;\nlet scannerCtx = null;\nlet zxingReader = null;\nlet zxingControls = null;\n\nasync function loadZXing() {\n  if (window.ZXingBrowser) return true;\n  if (window._zxingLoading) {\n    return await new Promise(resolve => {\n      const t=setInterval(()=>{ if(window.ZXingBrowser){clearInterval(t);resolve(true)} },100);\n      setTimeout(()=>{clearInterval(t);resolve(!!window.ZXingBrowser)},5000);\n    });\n  }\n  window._zxingLoading=true;\n  return await new Promise(resolve=>{\n    const sc=document.createElement('script');\n    sc.src='https://unpkg.com/@zxing/browser@0.1.5/umd/index.min.js';\n    sc.onload=()=>{window._zxingLoading=false;resolve(!!window.ZXingBrowser)};\n    sc.onerror=()=>{window._zxingLoading=false;resolve(false)};\n    document.head.appendChild(sc);\n  });\n}\n\n\n// Check for native BarcodeDetector API\nif ('BarcodeDetector' in window) {\n  barcodeDetector = new BarcodeDetector({ formats: ['ean_13','ean_8','upc_a','upc_e','code_128','code_39','qr_code','itf','codabar'] });\n}\n\ndocument.getElementById('btnCamera').onclick = openScanner;\ndocument.getElementById('btnVisual').onclick = openVisual;\n\nasync function openScanner() {\n  document.getElementById('scannerOverlay').classList.add('show');\n  document.getElementById('scannerDetected').textContent = '';\n  document.getElementById('barcodeInput').value = '';\n  document.getElementById('scannerBadge').textContent = 'Avvio scanner…';\n\n  try {\n    if (!navigator.mediaDevices?.getUserMedia) throw new Error('Camera non disponibile');\n    scannerStream = await navigator.mediaDevices.getUserMedia({\n      video:{facingMode:{ideal:'environment'},width:{ideal:1280},height:{ideal:720}}\n    });\n    const video=document.getElementById('scannerVideo');\n    video.srcObject=scannerStream;\n    await video.play();\n\n    if (barcodeDetector) {\n      document.getElementById('scannerBadge').textContent='Scanner attivo — inquadra EAN/UPC';\n      startScanLoop();\n      return;\n    }\n\n    const ok=await loadZXing();\n    if (ok && window.ZXingBrowser?.BrowserMultiFormatReader) {\n      document.getElementById('scannerBadge').textContent='Scanner attivo — inquadra il codice';\n      zxingReader=new window.ZXingBrowser.BrowserMultiFormatReader();\n      try {\n        zxingControls=await zxingReader.decodeFromVideoElement(video,(result,err)=>{\n          if(result){\n            onBarcodeDetected(result.getText(), result.getBarcodeFormat?.() || 'BARCODE');\n          }\n        });\n        return;\n      } catch(e){ console.warn('ZXing scanner error',e); }\n    }\n\n    // Last-resort QR fallback.\n    if (!window.jsQR) {\n      const sc=document.createElement('script');\n      sc.src='https://cdn.jsdelivr.net/npm/jsqr@1.4.0/dist/jsQR.min.js';\n      document.head.appendChild(sc);\n    }\n    document.getElementById('scannerBadge').textContent='Scanner base attivo';\n    startScanLoop();\n  } catch(err) {\n    console.warn('Camera scanner:',err);\n    document.getElementById('scannerBadge').textContent='Fotocamera non disponibile';\n    document.getElementById('scannerDetected').textContent='Inserisci il codice manualmente';\n    document.getElementById('barcodeInput').focus();\n  }\n}\n\nfunction startScanLoop() {\n  const video=document.getElementById('scannerVideo');\n  if(!video.srcObject) return;\n  async function scanFrame(){\n    if(video.readyState<video.HAVE_ENOUGH_DATA){\n      scannerRAF=requestAnimationFrame(scanFrame); return;\n    }\n    if(barcodeDetector){\n      try{\n        const barcodes=await barcodeDetector.detect(video);\n        if(barcodes?.length){\n          onBarcodeDetected(barcodes[0].rawValue,barcodes[0].format);\n          return;\n        }\n      }catch{}\n    }\n    if(window.jsQR){\n      try{\n        if(!scannerCanvas){\n          scannerCanvas=document.createElement('canvas');\n          scannerCtx=scannerCanvas.getContext('2d',{willReadFrequently:true});\n        }\n        scannerCanvas.width=video.videoWidth;\n        scannerCanvas.height=video.videoHeight;\n        scannerCtx.drawImage(video,0,0);\n        const data=scannerCtx.getImageData(0,0,scannerCanvas.width,scannerCanvas.height);\n        const qr=window.jsQR(data.data,data.width,data.height,{inversionAttempts:'attemptBoth'});\n        if(qr?.data){onBarcodeDetected(qr.data,'QR_CODE');return;}\n      }catch{}\n    }\n    scannerRAF=requestAnimationFrame(scanFrame);\n  }\n  scannerRAF=requestAnimationFrame(scanFrame);\n}\n\nfunction onBarcodeDetected(code, format) {\n  // Flash effect\n  const flash = document.getElementById('scannerFlash');\n  flash.classList.add('on');\n  setTimeout(() => flash.classList.remove('on'), 200);\n\n  // Show detected code\n  document.getElementById('scannerDetected').textContent = `✅ Rilevato: ${code}`;\n  document.getElementById('scannerBadge').textContent = `Codice ${format || ''} rilevato!`;\n  document.getElementById('barcodeInput').value = code;\n\n  // Vibrate if supported\n  if (navigator.vibrate) navigator.vibrate(100);\n\n  // Auto-search after brief delay\n  setTimeout(() => {\n    closeScanner();\n    searchBarcodeByCode(code);\n  }, 600);\n}\n\nfunction closeScanner() {\n  document.getElementById('scannerOverlay').classList.remove('show');\n  if (scannerRAF) { cancelAnimationFrame(scannerRAF); scannerRAF = null; }\n  if (zxingControls) { try { zxingControls.stop(); } catch {} zxingControls=null; }\n  if (zxingReader) { try { zxingReader.reset(); } catch {} zxingReader=null; }\n  if (scannerStream) {\n    scannerStream.getTracks().forEach(t => t.stop());\n    scannerStream = null;\n  }\n  const video = document.getElementById('scannerVideo');\n  video.srcObject = null;\n}\n\nfunction searchBarcode() {\n  const code = document.getElementById('barcodeInput').value.trim();\n  if (!code) return;\n  closeScanner();\n  searchBarcodeByCode(code);\n}\n\nasync function searchBarcodeByCode(code) {\n  searchInput.value = `Barcode: ${code}`;\n  showLoading();\n  try {\n    const r = await fetch(`/api/barcode?code=${encodeURIComponent(code)}`);\n    const d = await r.json();\n    if(!r.ok) throw new Error(d.error||'Ricerca visiva non riuscita');\n    S.lastResults = d.results || [];\n    S.lastIntent = { kind: d.kind || 'product', used: false, cheap: false, near: false, openNow: false, coreTerms: d.productName ? [d.productName] : [code], terms: [code], sort: 'best' };\n    if (d.aiAnswer) {\n      document.getElementById('aiAnswer').style.display = '';\n      document.getElementById('aiText').textContent = d.aiAnswer;\n    } else {\n      document.getElementById('aiAnswer').style.display = 'none';\n    }\n    renderResults(S.lastResults);\n    addHistory(`Barcode: ${code}`);\n  } catch (e) {\n    showToast('Errore ricerca barcode', 'err');\n    hideLoading();\n  }\n}\n\n// Enter in barcode input\ndocument.getElementById('barcodeInput').addEventListener('keydown', e => { if (e.key === 'Enter') searchBarcode(); });\n\n/* ========== BARCODE PHOTO ========== */\nconst barcodeImgInput=document.getElementById('barcodeImgInput');\nif(barcodeImgInput) barcodeImgInput.addEventListener('change', async function(){\n  const file=this.files?.[0]; this.value=''; if(!file)return;\n  const status=document.getElementById('scannerDetected');\n  try{\n    const url=URL.createObjectURL(file), img=new Image();\n    img.onload=async()=>{\n      try{\n        const max=1800, scale=Math.min(1,max/Math.max(img.width,img.height));\n        const c=document.createElement('canvas'); c.width=Math.max(1,Math.round(img.width*scale)); c.height=Math.max(1,Math.round(img.height*scale));\n        c.getContext('2d',{willReadFrequently:true}).drawImage(img,0,0,c.width,c.height);\n        if(barcodeDetector){try{const found=await barcodeDetector.detect(await createImageBitmap(c));if(found?.length){closeScanner();searchBarcodeByCode(found[0].rawValue);return}}catch{}}\n        const ok=await loadZXing();\n        if(ok&&window.ZXingBrowser?.BrowserMultiFormatReader){\n          const reader=new window.ZXingBrowser.BrowserMultiFormatReader();\n          try{const result=await reader.decodeFromImageUrl(c.toDataURL('image/jpeg',0.95));if(result?.getText){closeScanner();searchBarcodeByCode(result.getText());return}}catch{}\n        }\n        if(status)status.textContent='Barcode non letto. Usa una foto ravvicinata, ben illuminata e con il codice ben visibile.';\n      }finally{URL.revokeObjectURL(url)}\n    };\n    img.onerror=()=>{URL.revokeObjectURL(url);if(status)status.textContent='Impossibile aprire la foto.'}; img.src=url;\n  }catch(e){if(status)status.textContent='Impossibile leggere la foto del barcode.'}\n});\n\n/* ========== VISUAL SEARCH (REAL CAMERA) ========== */\nlet visStream = null;\nlet visCamFacing = 'environment';\nlet visMode = 'cam'; // 'cam' or 'file'\nlet visCapturedImage = null; // base64 data URL of captured image\n\nfunction openVisual() {\n  document.getElementById('visualOverlay').classList.add('show');\n  document.getElementById('previewImg').style.display = 'none';\n  document.getElementById('visDescInput').value = '';\n  document.getElementById('visCamWrap').classList.add('on');\n  document.getElementById('uploadArea').style.display = 'none';\n  document.getElementById('imgInput').value = '';\n  visCapturedImage = null;\n  setVisMode('cam');\n  startVisCamera();\n}\n\nfunction closeVisual() {\n  document.getElementById('visualOverlay').classList.remove('show');\n  stopVisCamera();\n}\n\nfunction setVisMode(mode) {\n  visMode = mode;\n  document.getElementById('visModeCam').classList.toggle('on', mode === 'cam');\n  document.getElementById('visModeFile').classList.toggle('on', mode === 'file');\n  if (mode === 'cam') {\n    document.getElementById('visCamWrap').classList.add('on');\n    document.getElementById('uploadArea').style.display = 'none';\n    startVisCamera();\n  } else {\n    document.getElementById('visCamWrap').classList.remove('on');\n    document.getElementById('uploadArea').style.display = '';\n    stopVisCamera();\n  }\n}\n\nasync function startVisCamera() {\n  if (visStream) return; // already running\n  try {\n    visStream = await navigator.mediaDevices.getUserMedia({\n      video: { facingMode: visCamFacing, width: { ideal: 1920 }, height: { ideal: 1080 } }\n    });\n    const video = document.getElementById('visVideo');\n    video.srcObject = visStream;\n    await video.play();\n  } catch (err) {\n    console.warn('Visual search camera error:', err);\n    // Fallback to file mode\n    setVisMode('file');\n  }\n}\n\nfunction stopVisCamera() {\n  if (visStream) {\n    visStream.getTracks().forEach(t => t.stop());\n    visStream = null;\n  }\n  const video = document.getElementById('visVideo');\n  video.srcObject = null;\n}\n\nfunction visSwitchCam() {\n  visCamFacing = visCamFacing === 'environment' ? 'user' : 'environment';\n  stopVisCamera();\n  startVisCamera();\n}\n\nfunction visSnap() {\n  const video = document.getElementById('visVideo');\n  const canvas = document.getElementById('visCanvas');\n  canvas.width = video.videoWidth;\n  canvas.height = video.videoHeight;\n  const ctx = canvas.getContext('2d');\n  ctx.drawImage(video, 0, 0);\n  const maxSide=1280;\n  const scale=Math.min(1,maxSide/Math.max(canvas.width,canvas.height));\n  const outCanvas=document.createElement('canvas');\n  outCanvas.width=Math.max(1,Math.round(canvas.width*scale));\n  outCanvas.height=Math.max(1,Math.round(canvas.height*scale));\n  outCanvas.getContext('2d').drawImage(canvas,0,0,outCanvas.width,outCanvas.height);\n  visCapturedImage=outCanvas.toDataURL('image/jpeg',0.72);\n\n  // Show preview\n  document.getElementById('previewImg').src = visCapturedImage;\n  document.getElementById('previewImg').style.display = '';\n  document.getElementById('visDescInput').placeholder = 'Descrivi cosa vedi nella foto...';\n\n  // Vibrate\n  if (navigator.vibrate) navigator.vibrate(50);\n\n  showToast('📸 Foto catturata!', 'ok');\n}\n\n// File input handler\ndocument.getElementById('imgInput').onchange = async function(){\n  const file=this.files?.[0]; this.value=''; if(!file)return;\n  try{\n    if(!file.type.startsWith('image/')) throw new Error('Il file selezionato non è un\\'immagine.');\n    const url=URL.createObjectURL(file), img=new Image();\n    img.onload=()=>{\n      try{\n        const maxSide=1600, scale=Math.min(1,maxSide/Math.max(img.width,img.height));\n        const c=document.createElement('canvas'); c.width=Math.max(1,Math.round(img.width*scale)); c.height=Math.max(1,Math.round(img.height*scale));\n        c.getContext('2d',{alpha:false}).drawImage(img,0,0,c.width,c.height);\n        visCapturedImage=c.toDataURL('image/jpeg',0.82);\n        document.getElementById('previewImg').src=visCapturedImage;\n        document.getElementById('previewImg').style.display='';\n        document.getElementById('visDescInput').placeholder='Aggiungi un dettaglio se vuoi una ricerca ancora più precisa…';\n        showToast('📁 Foto caricata correttamente','ok');\n      }catch(e){showToast('Impossibile preparare la foto','err')}\n      finally{URL.revokeObjectURL(url)}\n    };\n    img.onerror=()=>{URL.revokeObjectURL(url);showToast('Formato foto non supportato dal browser','err')}; img.src=url;\n  }catch(e){showToast(e.message||'Errore caricamento foto','err')}\n};\n\nasync function doVisualSearch() {\n  const description = document.getElementById('visDescInput').value.trim();\n  if (!description && !visCapturedImage) {\n    showToast('Scatta una foto o descrivi l\\'oggetto', 'warn');\n    return;\n  }\n\n  closeVisual();\n  searchInput.value = description || 'Ricerca visiva...';\n  showLoading();\n\n  try {\n    const r = await fetch('/api/visual-search', {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({\n        image: visCapturedImage || null,\n        description: description || null\n      })\n    });\n    const d = await r.json().catch(()=>({error:'Risposta server non valida'}));\n    if(!r.ok) throw new Error(d.error || `Errore server ${r.status}`);\n    S.lastResults = d.results || [];\n    const visualTerms = [d.identified?.brand, d.identified?.model, d.identified?.product, d.identified?.variant].filter(Boolean);\n    S.lastIntent = { kind: d.kind || 'product', used: false, cheap: false, near: false, openNow: false, coreTerms: visualTerms.length ? visualTerms : [description || 'visual search'], terms: visualTerms.length ? visualTerms : [description || 'visual search'], sort: 'best' };\n    S.lastResults = applyLearning(S.lastResults);\n    if (d.aiAnswer) {\n      document.getElementById('aiAnswer').style.display = '';\n      document.getElementById('aiText').textContent = d.aiAnswer;\n    } else {\n      document.getElementById('aiAnswer').style.display = 'none';\n    }\n    renderResults(S.lastResults);\n    addHistory(description || 'Ricerca visiva');\n  } catch (e) {\n    // Fallback: search by description directly\n    if (description) {\n      doSearch(description);\n    } else {\n      showToast('Ricerca visiva non riuscita. Riprova con una foto più nitida.', 'err');\n      hideLoading();\n    }\n  }\n}\n\n/* ========== SHARE ========== */\nfunction shareResult(id) {\n  const r = S.lastResults.find(x=>x.id===id);\n  if(!r) return;\n  const shareData = {\n    title: 'FINDO: ' + r.title,\n    text: `${r.title} — €${r.price!=null?Number(r.price).toLocaleString('it'):'?'} · ${r.source}`,\n    url: r.url\n  };\n  if(navigator.share) {\n    navigator.share(shareData).catch(()=>copyShare(r));\n  } else {\n    copyShare(r);\n  }\n}\n\nfunction copyShare(r) {\n  const text = `${r.title} — €${r.price!=null?Number(r.price).toLocaleString('it'):'?'} · ${r.source} · ${r.url}`;\n  navigator.clipboard.writeText(text).then(()=>showToast(t('shared'),'ok'));\n}\n\n/* ========== EXTRACT (on-demand) ========== */\nasync function extractDetail(url) {\n  try {\n    const r = await fetch('/api/extract',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({urls:[url]})});\n    const d = await r.json();\n    if(d.results?.[0]?.content) return d.results[0].content.slice(0,500);\n  } catch(e) {}\n  return null;\n}\n\n/* ========== TOAST ========== */\nlet toastTimer;\nfunction showToast(msg, type='') {\n  const el = document.getElementById('toast');\n  el.textContent = msg;\n  el.className = 'toast show' + (type?' toast-'+type:'');\n  clearTimeout(toastTimer);\n  toastTimer = setTimeout(()=>el.className='toast', 2500);\n}\n\n/* ========== UTILS ========== */\nfunction esc(s) { return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/\"/g,'&quot;').replace(/'/g,'&#39;'); }\n\n/* ========== SCROLL FAB ========== */\nwindow.addEventListener('scroll', () => {\n  document.getElementById('fabTop').classList.toggle('show', window.scrollY > 400);\n});\n\n/* ========== SERVICE WORKER ========== */\nif('serviceWorker' in navigator) {\n  navigator.serviceWorker.register('/sw.js?v=10.0').catch(()=>{});\n}\n\n/* ========== INIT ========== */\nloadSavedSearches();\n\n// Check URL params for shared search\nconst params = new URLSearchParams(location.search);\nif(params.get('q')) doSearch(params.get('q'));\n</script>\n</body>\n</html>";
